import json,glob
for f in sorted(glob.glob('*/*.json')):
    d=json.load(open(f))
    print('=====',f)
    for i,m in enumerate(d['messages']):
        if m['role']=='assistant':
            c=m.get('content') or ''
            print(i,'A:',c[:600].replace('\n',' '))
            for t in m.get('tool_calls') or []:
                print(i,'  CALL',t['function']['name'],t['function']['arguments'][:400].replace('\n',' '))
        elif m['role']=='tool':
            print(i,'  T:',(m.get('content') or '')[:200].replace('\n',' '))
        else:
            print(i,m['role'],(m.get('content') or '')[:300].replace('\n',' '))
